entries[7450] = { ["name"] = "Muster: Grünwelpenrüstung", ["text"] = "Benötigt Lederverarbeitung (175)\nBenutzen: Lehrt Euch die Herstellung einer Grünwelpenrüstung.\nGrünwelpenrüstung\nWird beim Anlegen gebunden\nBrust Leder\n102 Rüstung\n+11 Willenskraft\nHaltbarkeit 85 / 85\nBenötigt Stufe 30\nAnlegen: Bei einem Treffer durch einen Nahkampfangreifer hat dieser Angreifer eine Chance von 5%, 10 sec lang in Schlaf versetzt zu werden. Wirkt nur bei Gegnern der Stufe 50 oder niedriger. (Procchance: 5%)\nBenötigt Grünwelpenschuppe (4), Schweres Leder (10), Feiner Faden (2)" }
entries[7451] = { ["name"] = "Muster: Grünwelpenarmschienen", ["text"] = "Benötigt Lederverarbeitung (190)\nBenutzen: Lehrt Euch die Herstellung von Grünwelpenarmschienen.\nGrünwelpenarmschienen\nWird beim Anlegen gebunden\nHandgelenke Leder\n47 Rüstung\n+4 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Stufe 33\nAnlegen: Erhöht die kritische Trefferwertung um 4.\nAnlegen: Erhöht die Trefferwertung um 4.\nBenötigt Grünwelpenschuppe (6), Schweres Leder (8), Seidenfaden (2)" }
