entries[8801] = { ["name"] = "Buch der Gelassenheit IV", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Gelassenheit' (Rang 1).\nHeilt bei allen in der Nähe befindlichen Gruppenmitgliedern 8 sec lang alle 2 Sek. 365 Gesundheit. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[8802] = { ["name"] = "Foliant der arkanen Intelligenz", ["text"] = "Klassen: Magier\nBenutzen: Lehrt 'Arkane Intelligenz' (Rang 2).\nErhöht 30 min lang die Intelligenz des Ziels um 7." }
entries[8804] = { ["name"] = "Foliant der arkanen Explosion", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nSchleudert arkane Geschosse auf den Feind und verursacht 3 sec lang alle 1 Sek. 26 Arkanschaden." }
entries[8805] = { ["name"] = "Foliant des Magieentdeckens", ["text"] = "Klassen: Magier\nBenötigt Stufe 16\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 11 verringert werden. Hält 10 min lang an." }
entries[8806] = { ["name"] = "Foliant der geringen Fluchaufhebung", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Fluch aufheben'.\nBefreit ein befreundetes Ziel von 1 Fluch." }
entries[8807] = { ["name"] = "Foliant des Magieverstärkens", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 11 verringert werden. Hält 10 min lang an." }
entries[8808] = { ["name"] = "Foliant des Manaschilds", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Blizzard' (Rang 1).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 sec lang insgesamt [Quellwert] Frostschaden.", ["unresolvedValues"] = true }
entries[8809] = { ["name"] = "Foliant des Schlafes", ["text"] = "Klassen: Magier\nBenötigt Stufe 8\nBenutzen: Lehrt 'Schlaf' (Rang 1).\nVersetzt das feindliche Ziel bis zu 20 sec lang in Schlaf. Jeglicher zugefügte Schaden wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel schlafen. Unzuverlässig gegen Ziele über Stufe 30." }
entries[8810] = { ["name"] = "Foliant des Schlafes II", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Frostblitz' (Rang 2).\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 6 sec lang um 40% verringert.", ["unresolvedValues"] = true }
